fr.exercice_solution:
fun main() {
    data class TacheSimple(val titre: String, val estCompletee: Boolean)

    val taches = mutableListOf(
        TacheSimple(titre = 'Faire les courses', estCompletee = false),
        TacheSimple(titre = 'Appeler le medecin', estCompletee = true),
        TacheSimple(titre = 'Faire du sport', estCompletee = false),
        TacheSimple(titre = 'Lire un livre', estCompletee = true)
    )

    val tachesActives = taches.filter { !it.estCompletee }

    val titresEnMajuscule = tachesActives.map { it.titre.uppercase() }

    println('Nombre de taches actives : ${tachesActives.count()}')

    titresEnMajuscule.forEach { println(it) }
}

