en.exercice_solution:
fun main() {
    data class SimpleTask(val title: String, val isCompleted: Boolean)

    val tasks = mutableListOf(
        SimpleTask(title = 'Buy groceries', isCompleted = false),
        SimpleTask(title = 'Call the doctor', isCompleted = true),
        SimpleTask(title = 'Work out', isCompleted = false),
        SimpleTask(title = 'Read a book', isCompleted = true)
    )

    val activeTasks = tasks.filter { !it.isCompleted }

    val titlesUppercase = activeTasks.map { it.title.uppercase() }

    println('Number of active tasks: ${activeTasks.count()}')

    titlesUppercase.forEach { println(it) }
}
